// BASIC UNION-FIND (without optimisations)
class UnionFind {
    constructor(n) {
        this.parent = Array.from({length: n}, (_, i) => i); // parent[i] = i
        this.components = n; // track number of connected components
    }

    // FIND: follow parent pointers to the root
    find(x) {
        while (this.parent[x] !== x) {
            x = this.parent[x];
        }
        return x; // x is the root
    }

    // UNION: merge components of x and y
    // Returns true if they were in different components, false if same
    union(x, y) {
        const rootX = this.find(x);
        const rootY = this.find(y);
        if (rootX === rootY) return false; // already connected: cycle!
        this.parent[rootX] = rootY; // attach rootX to rootY
        this.components--;
        return true;
    }

    // Check if x and y are in the same component
    connected(x, y) {
        return this.find(x) === this.find(y);
    }
}

// TEST
const uf = new UnionFind(5); // nodes 0,1,2,3,4
console.log(uf.components); // 5
uf.union(0, 1); // merge 0 and 1
uf.union(1, 2); // merge 1 and 2 (0,1,2 all connected)
console.log(uf.components); // 3
console.log(uf.connected(0, 2)); // true (0->1->2 connected)
console.log(uf.connected(0, 3)); // false (3 not yet connected)
console.log(uf.union(0, 2));     // false: already same component = CYCLE

