// UNION-FIND with path compression and union-by-rank
class UnionFind {
    constructor(n) {
        this.parent = Array.from({length: n}, (_, i) => i);
        this.rank   = new Array(n).fill(0); // initial rank 0
        this.components = n;
    }

    // FIND with path compression: O(α(n)) amortised
    find(x) {
        if (this.parent[x] !== x) {
            this.parent[x] = this.find(this.parent[x]); // PATH COMPRESSION
        }
        return this.parent[x];
    }

    // UNION by rank: attach smaller rank tree under larger rank root
    union(x, y) {
        const rootX = this.find(x);
        const rootY = this.find(y);
        if (rootX === rootY) return false; // same component

        // UNION BY RANK: attach lower rank under higher rank
        if (this.rank[rootX] < this.rank[rootY]) {
            this.parent[rootX] = rootY;
        } else if (this.rank[rootX] > this.rank[rootY]) {
            this.parent[rootY] = rootX;
        } else {
            // Equal rank: attach rootX under rootY, increment rootY's rank
            this.parent[rootX] = rootY;
            this.rank[rootY]++;
        }
        this.components--;
        return true;
    }

    connected(x, y) { return this.find(x) === this.find(y); }
}

// PATH COMPRESSION TRACE:
// parent before: [1, 2, 3, 3]  (chain: 0->1->2->3, root=3)
// find(0):
//   find(parent[0]=1) -> find(parent[1]=2) -> find(parent[2]=3) -> return 3
//   parent[2] = 3 (already pointed to root)
//   parent[1] = 3 (compressed: skip 2)
//   parent[0] = 3 (compressed: skip 1 and 2)
// parent after: [3, 3, 3, 3]  (all point directly to root)
// Next find(0): O(1)!  parent[0]=3 directly

