// REDUNDANT CONNECTION (#684)
// O(E * α(V)) time, O(V) space
function findRedundantConnection(edges) {
    const n = edges.length; // n nodes, n edges
    const uf = new UnionFind(n + 1); // 1-indexed nodes

    for (const [u, v] of edges) {
        if (!uf.union(u, v)) {
            return [u, v]; // u and v already connected: this edge is redundant
        }
    }
    return []; // unreachable: problem guarantees one redundant edge
}

