// ACCOUNTS MERGE (#721) — Union-Find on email addresses
// Each account has a name and emails. Merge accounts that share an email.
// Union-Find approach: map each email to an account index
// For each account, union all its emails to the first email's account
function accountsMerge(accounts) {
    const emailToId = new Map();  // email -> account index
    const uf = new UnionFind(accounts.length);

    accounts.forEach((account, i) => {
        const emails = account.slice(1);
        for (const email of emails) {
            if (emailToId.has(email)) {
                uf.union(i, emailToId.get(email)); // merge accounts
            } else {
                emailToId.set(email, i);
            }
        }
    });

    // Group emails by root account
    const roots = new Map();
    for (const [email, id] of emailToId) {
        const root = uf.find(id);
        if (!roots.has(root)) roots.set(root, []);
        roots.get(root).push(email);
    }

    return [...roots.entries()].map(([root, emails]) => {
        emails.sort();
        return [accounts[root][0], ...emails];
    });
}

