// KRUSKAL'S MST ALGORITHM
// O(E log E) time, O(V+E) space
function kruskalMST(n, edges) {
    // edges: [[weight, u, v], ...]
    edges.sort((a, b) => a[0] - b[0]); // sort by weight ascending

    const uf = new UnionFind(n);
    let mstWeight = 0;
    let edgesUsed = 0;
    const mstEdges = [];

    for (const [w, u, v] of edges) {
        if (uf.union(u, v)) {   // no cycle: add to MST
            mstWeight += w;
            mstEdges.push([u, v, w]);
            edgesUsed++;
            if (edgesUsed === n - 1) break; // MST complete: V-1 edges
        }
        // If union returns false: edge creates cycle, skip it
    }
    return { mstWeight, mstEdges, connected: edgesUsed === n - 1 };
}

