// MIN COST TO CONNECT ALL POINTS (#1584)
// Points on a 2D plane, connect all with minimum Manhattan distance edges
function minCostConnectPoints(points) {
    const n = points.length;

    // Generate all edges (N*(N-1)/2 edges)
    const allEdges = [];
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            const dist = Math.abs(points[i][0] - points[j][0]) +
                         Math.abs(points[i][1] - points[j][1]);
            allEdges.push([dist, i, j]);
        }
    }

    // Sort and run Kruskal
    allEdges.sort((a, b) => a[0] - b[0]);
    const uf = new UnionFind(n);
    let totalCost = 0, edgesUsed = 0;

    for (const [dist, i, j] of allEdges) {
        if (uf.union(i, j)) {
            totalCost += dist;
            edgesUsed++;
            if (edgesUsed === n - 1) break;
        }
    }
    return totalCost;
}

